function InternationalPage({ openChat, setShowIntlModal }) {
  return (
    <div style={{ padding:"48px 20px", background:"#f8f9fa", minHeight:"60vh" }}>
      <div style={{ maxWidth:"1100px", margin:"0 auto" }}>
        <div style={{ textAlign:"center", marginBottom:"32px" }}>
          <p style={{ color:"#840A18", fontWeight:"800", fontSize:"11px", letterSpacing:"2px", marginBottom:"6px" }}>GLOBAL EDUCATION</p>
          <h2 style={{ fontSize:"28px", fontWeight:"900", color:"#1f2937", margin:"0 0 6px" }}>International Pathways at AGC</h2>
          <p style={{ color:"#6b7280", fontSize:"13px" }}>22 Global Partnerships Across 10+ Countries</p>
        </div>

        {/* Overview */}
        <div style={{ background:"white", borderRadius:"12px", padding:"28px 32px", boxShadow:"0 4px 20px rgba(0,0,0,0.08)", marginBottom:"28px" }}>
          <div style={{ borderLeft:"4px solid #840A18", paddingLeft:"18px", marginBottom:"20px" }}>
            <h3 style={{ margin:"0 0 4px", fontSize:"17px", fontWeight:"800", color:"#1f2937" }}>Our International Education Philosophy</h3>
          </div>
          {[
            "Amritsar Group of Colleges (AGC) is committed to nurturing global perspectives through select international academic collaborations and overseas education pathways. Our approach to international education in Punjab is grounded in academic relevance, quality assurance, and student-centric outcomes.",
            "AGC's international collaborations span New Zealand, Australia, Canada, France, South Africa, Indonesia, Nepal, Thailand, Trinidad & Tobago, and more — connecting our students with globally recognized institutions and industry networks.",
            "Through structured student exchange programs, dual-degree pathways, joint research initiatives, and overseas education consultancies, AGC provides students with genuine international exposure that enhances employability and global awareness.",
            "Our Dean of International Education works closely with 22 partner institutions to ensure seamless transfer of credits, joint faculty programs, and industry-connect opportunities for AGC students seeking a global career."
          ].map((p,i)=>(
            <p key={i} style={{ fontSize:"14px", lineHeight:"1.8", color:"#374151", marginBottom:"14px" }}>{p}</p>
          ))}
          <div style={{ display:"flex", flexWrap:"wrap", gap:"10px" }}>
            <button onClick={() => openChat("Tell me about international study options and dual degree programs at AGC. What countries can I study in?")}
              style={{ background:"#840A18", color:"white", border:"none", padding:"10px 18px", borderRadius:"6px", fontWeight:"700", fontSize:"12px", cursor:"pointer", display:"flex", alignItems:"center", gap:"6px" }}>
              <Bot size={14}/> Ask AI About International Programs
            </button>
            <button onClick={() => setShowIntlModal(true)}
              style={{ background:"#002147", color:"white", border:"none", padding:"10px 18px", borderRadius:"6px", fontWeight:"700", fontSize:"12px", cursor:"pointer", display:"flex", alignItems:"center", gap:"6px" }}>
              <Globe size={14}/> International Admissions — How to Apply
            </button>
          </div>
        </div>

        {/* Table */}
        <h3 style={{ fontSize:"17px", fontWeight:"800", color:"#1f2937", marginBottom:"14px" }}>International Collaboration Partners</h3>
        <div style={{ background:"white", borderRadius:"10px", overflow:"hidden", boxShadow:"0 4px 20px rgba(0,0,0,0.08)" }}>
          <div style={{ overflowX:"auto" }}>
            <table style={{ width:"100%", fontSize:"12px", borderCollapse:"collapse", minWidth:"600px" }}>
              <thead>
                <tr style={{ background:"#002147", color:"white" }}>
                  {["S.No","Institution Name","Country","Nature of Collaboration"].map(h=>(
                    <th key={h} style={{ padding:"12px 14px", textAlign:"left", fontWeight:"800" }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {INTL_COLLABS.map((c,i)=>(
                  <tr key={c.sno} style={{ background:i%2===0?"white":"#f8fafd", borderBottom:"1px solid #f0f0f0" }}>
                    <td style={{ padding:"10px 14px", color:"#9ca3af", fontWeight:"600" }}>{c.sno}</td>
                    <td style={{ padding:"10px 14px", fontWeight:"600", color:"#1f2937" }}>{c.name}</td>
                    <td style={{ padding:"10px 14px" }}>
                      <span style={{ display:"flex", alignItems:"center", gap:"5px", color:"#374151" }}>
                        <Globe size={11} color="#002147"/> {c.country}
                      </span>
                    </td>
                    <td style={{ padding:"10px 14px" }}>
                      <span style={{ background:"#e0f2fe", color:"#0369a1", fontSize:"11px", fontWeight:"600", padding:"2px 8px", borderRadius:"4px" }}>{c.nature}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

